import React, { useState } from 'react';
import Button from '@mui/material/Button';
import MenuIcon from '@mui/icons-material/Menu';
import { AiOutlineMenuFold, AiOutlineMenuUnfold } from "react-icons/ai";

function Header() {
  const [menuOpen, setMenuOpen] = useState(false);

  const handleMenuToggle = () => {
    setMenuOpen(!menuOpen);
  };

  return (
    <>
      <header className="w-full py-3 px-6 shadow-md bg-white border-b border-[rgba(0,0,0,0.1)] flex items-center justify-between">
        {/* Left Section: Menu Button */}
        <div className="flex items-center">
          <Button
            onClick={handleMenuToggle}
            className="!w-[40px] !h-[40px] !rounded-full !min-w-[40px] text-[rgba(0,0,0,0.8)]"
          >
            {menuOpen ? (
              <AiOutlineMenuUnfold className="text-black text-[22px]" />
            ) : (
              <AiOutlineMenuFold className="text-black text-[22px]" />
            )}
          </Button>
        </div>

        {/* Right Section: Buttons */}
        <div className="flex items-center gap-3">
          <Button
            variant="contained"
            className="!bg-[#ff5252] !text-white !normal-case !px-5 !py-2 !rounded-md hover:!bg-[#e64545]"
          >
            Sign in
          </Button>
        </div>
      </header>
    </>
  );
}

export default Header;
